import{_ as n,c as a,b as s,o as l}from"./app-D79r4NlB.js";const i={};function r(t,e){return l(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="层叠、优先级与继承" tabindex="-1"><a class="header-anchor" href="#层叠、优先级与继承"><span>层叠、优先级与继承</span></a></h1><ul><li><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Box_model" target="_blank" rel="noopener noreferrer">上一页</a></li><li><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics" target="_blank" rel="noopener noreferrer">概述：CSS 构建</a></li><li><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Values_and_units" target="_blank" rel="noopener noreferrer">下一页</a></li></ul><p>本文旨在让你理解 CSS 的一些最基本的概念——层叠、优先级和继承——这些概念决定着如何将 CSS 应用到 HTML 中，以及如何解决冲突。</p><p>尽管与课程的其他部分相比，完成这节课可能看起来没有那么直接的相关性，而且更学术性一些，但是理解这些东西将为你以后节省很多痛苦！我们希望你仔细阅读本节，并在继续下一步学习之前，确保你是否理解了这些概念。</p><table><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>前提：</td><td>基本的计算机知识、安装基本的软件、<a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Getting_started/Environment_setup/Dealing_with_files" target="_blank" rel="noopener noreferrer">文件处理</a>基本知识、HTML 基础知识（<a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Structuring_content" target="_blank" rel="noopener noreferrer">HTML 简介</a>），以及 CSS 如何工作的基本常识（<a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics" target="_blank" rel="noopener noreferrer">学习 CSS 第一步</a>）。</td></tr><tr><td>目标：</td><td>学习层叠、优先级，以及在 CSS 中继承是如何工作的。</td></tr></tbody></table><h2 id="冲突规则" tabindex="-1"><a class="header-anchor" href="#冲突规则"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E5%86%B2%E7%AA%81%E8%A7%84%E5%88%99" target="_blank" rel="noopener noreferrer">冲突规则</a></span></a></h2><p>CSS 代表<strong>层叠样式表</strong>（Cascading Style Sheets），理解第一个词_层叠_（cascade）很重要——层叠的表现方式是理解 CSS 的关键。</p><p>在某些时候，在做一个项目过程中你会发现一些应该产生效果的样式没有生效。通常的原因是你创建了两个应用于同一个元素的规则。与<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Guides/Cascade/Introduction" target="_blank" rel="noopener noreferrer"><strong>层叠</strong></a>密切相关的概念是<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Guides/Cascade/Specificity" target="_blank" rel="noopener noreferrer"><strong>优先级</strong>（specificity）</a>，决定在发生冲突的时候应该使用哪条规则。设计元素样式的规则可能不是期望的规则，因此需要了解这些机制是如何工作的。</p><p>这里也有<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Guides/Cascade/Inheritance" target="_blank" rel="noopener noreferrer"><strong>继承</strong></a>的概念，也就是在默认情况下，一些 css 属性继承当前元素的父元素上设置的值，有些则不继承。这也可能导致一些和期望不同的结果。</p><p>我们来快速地看下正在处理的关键问题，然后依次了解它们是如何相互影响的，以及如何和 CSS 交互的。虽然这些概念难以理解，但是随着不断的练习，你会慢慢熟悉它的工作原理。</p><h3 id="层叠" tabindex="-1"><a class="header-anchor" href="#层叠"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E5%B1%82%E5%8F%A0" target="_blank" rel="noopener noreferrer">层叠</a></span></a></h3><p>样式表<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Guides/Cascade/Introduction" target="_blank" rel="noopener noreferrer"><strong>层叠</strong></a>——当两条同级别的规则应用到一个元素的时候，在后面的会覆盖前面的规则。</p><p>下面的示例中，我们有两个关于 <code>&amp;lt;h1&amp;gt;</code> 的规则。<code>&amp;lt;h1&amp;gt;</code> 最后显示蓝色——这两个规则来自同一个源，且具有相同的元素选择器，有相同的优先级，所以顺序在最后的生效。</p><p>htmlCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=1323a7f02277a48e8af09ab61c1b964756df1734&amp;state=q1bKKMnNUbJSsskwtHuxf%2BazGeufdUx8Pqvl2YL2l4tmPG5ostHPMLSLyVPSUUouLlayUsowVKiOyVNQSM7PyS%2ByUihKTbGOyauNyUMTT8opTYVIKOkoZYE0KukolWSk5qYqWSnlZKZnlCjVAgA%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;h1&gt;这是我的标题。&lt;/h1&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>cssCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=1323a7f02277a48e8af09ab61c1b964756df1734&amp;state=q1bKKMnNUbJSsskwtHuxf%2BazGeufdUx8Pqvl2YL2l4tmPG5ostHPMLSLyVPSUUouLlayUsowVKiOyVNQSM7PyS%2ByUihKTbGOyauNyUMTT8opTYVIKOkoZYE0KukolWSk5qYqWSnlZKZnlCjVAgA%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">h1 {</span>
<span class="line">  color: red;</span>
<span class="line">}</span>
<span class="line">h1 {</span>
<span class="line">  color: blue;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://developer.mozilla.org/zh-CN/play?uuid=1323a7f02277a48e8af09ab61c1b964756df1734&amp;state=q1bKKMnNUbJSsskwtHuxf%2BazGeufdUx8Pqvl2YL2l4tmPG5ostHPMLSLyVPSUUouLlayUsowVKiOyVNQSM7PyS%2ByUihKTbGOyauNyUMTT8opTYVIKOkoZYE0KukolWSk5qYqWSnlZKZnlCjVAgA%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><h3 id="优先级" tabindex="-1"><a class="header-anchor" href="#优先级"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E4%BC%98%E5%85%88%E7%BA%A7" target="_blank" rel="noopener noreferrer">优先级</a></span></a></h3><p>浏览器是根据<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Guides/Cascade/Specificity" target="_blank" rel="noopener noreferrer">优先级</a>来决定，当有多个不同选择器对相同元素生效的时候需要使用哪个规则。它基本上是一个衡量选择器具体选择哪些区域的尺度：</p><ul><li>一个元素选择器不是很具体，则会选择页面上该类型的所有元素，所以它的优先级就会低一些。</li><li>一个类选择器稍微具体点，则会选择该页面中有特定 <code>class</code> 属性值的元素，所以它的优先级就要高一点。</li></ul><p>下面我们再来介绍两个适用于 <code>&amp;lt;h1&amp;gt;</code> 的规则。下面的 <code>&amp;lt;h1&amp;gt;</code> 最后会显示红色——类选择器 <code>main-heading</code> 有更高的优先级，因此就会被应用——即使元素选择器顺序在它后面。</p><p>htmlCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=21fe1871d391d195be5794fe99c99dd12bb3cec3&amp;state=q1bKKMnNUbJSsskwVEjOSSwuto1Ryk3MzNPNSE1MycxLj1Gye7F%2F5rMZ6591THw%2Bq%2BXZgvaXi2Y8bmiy0c8wtIvJU9JRSi4uVrJS0kPWpFAdk6egkJyfk19kpVCUmmIdk1cbkxeTl2GIIpOUU5oKkVLSUcoCmaKko1SSkZqbqmSllJOZnlGiVAsA&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;h1 class=&quot;main-heading&quot;&gt;这是我的标题。&lt;/h1&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>cssCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=21fe1871d391d195be5794fe99c99dd12bb3cec3&amp;state=q1bKKMnNUbJSsskwVEjOSSwuto1Ryk3MzNPNSE1MycxLj1Gye7F%2F5rMZ6591THw%2Bq%2BXZgvaXi2Y8bmiy0c8wtIvJU9JRSi4uVrJS0kPWpFAdk6egkJyfk19kpVCUmmIdk1cbkxeTl2GIIpOUU5oKkVLSUcoCmaKko1SSkZqbqmSllJOZnlGiVAsA&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">.main-heading {</span>
<span class="line">  color: red;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">h1 {</span>
<span class="line">  color: blue;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://developer.mozilla.org/zh-CN/play?uuid=21fe1871d391d195be5794fe99c99dd12bb3cec3&amp;state=q1bKKMnNUbJSsskwVEjOSSwuto1Ryk3MzNPNSE1MycxLj1Gye7F%2F5rMZ6591THw%2Bq%2BXZgvaXi2Y8bmiy0c8wtIvJU9JRSi4uVrJS0kPWpFAdk6egkJyfk19kpVCUmmIdk1cbkxeTl2GIIpOUU5oKkVLSUcoCmaKko1SSkZqbqmSllJOZnlGiVAsA&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><p>稍后我们会详细解释优先级算法。</p><h3 id="继承" tabindex="-1"><a class="header-anchor" href="#继承"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E7%BB%A7%E6%89%BF" target="_blank" rel="noopener noreferrer">继承</a></span></a></h3><p>继承也需要在上下文中去理解——一些设置在父元素上的 CSS 属性是可以被子元素继承的，有些则不能。</p><p>举一个例子，如果你设置一个元素的 <code>color</code> 和 <code>font-family</code>，每个在里面的元素也都会有相同的属性，除非你直接在元素上设置属性。</p><p>htmlCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=8aace7ce4d4434338f3e345448eb01a8fe8fd559&amp;state=XY1BToNAGIWvQv41SfdIOAmbFomodCCCC9M0ITVV0Wo1srBok4aIVmshNkZpoXIYZ4Zh1SuYinHh9n3ve68Fmt3UQQDRlArvFS8ucJKWwU0Z3DF3xoIJiz6LZYSTBbseMne2ynrkdkSn9ywOqw7OfBZMyPSSdA%2BLt1GRPlI3%2F3I6Ys2UZCSaEj25wukL6cc4DUvHZ%2Flx6bj07IkMxiTy8fK8EukwpN6c9H%2BvV1mPxh556LB8gJNn0TLrSCJHXRLN2ceYvZ%2BKtSr6kf%2F%2BgAfFskCAhrF5wLVkxHGKoRt7AtfQ99UNGbVlJKO1%2BQ%2FWld2KAg876wHgwdbUpgoC6Ntbmg3tbw%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;p&gt;由于主题颜色被设置为蓝色，因此该颜色会被子元素继承。&lt;/p&gt;</span>
<span class="line">&lt;p&gt;我们可以通过选择器定位元素来改变颜色，比如这个&lt;span&gt;内容跨越&lt;/span&gt;元素。&lt;/p&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>cssCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=8aace7ce4d4434338f3e345448eb01a8fe8fd559&amp;state=XY1BToNAGIWvQv41SfdIOAmbFomodCCCC9M0ITVV0Wo1srBok4aIVmshNkZpoXIYZ4Zh1SuYinHh9n3ve68Fmt3UQQDRlArvFS8ucJKWwU0Z3DF3xoIJiz6LZYSTBbseMne2ynrkdkSn9ywOqw7OfBZMyPSSdA%2BLt1GRPlI3%2F3I6Ys2UZCSaEj25wukL6cc4DUvHZ%2Flx6bj07IkMxiTy8fK8EukwpN6c9H%2BvV1mPxh556LB8gJNn0TLrSCJHXRLN2ceYvZ%2BKtSr6kf%2F%2BgAfFskCAhrF5wLVkxHGKoRt7AtfQ99UNGbVlJKO1%2BQ%2FWld2KAg876wHgwdbUpgoC6Ntbmg3tbw%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">body {</span>
<span class="line">  color: blue;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">span {</span>
<span class="line">  color: black;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://developer.mozilla.org/zh-CN/play?uuid=8aace7ce4d4434338f3e345448eb01a8fe8fd559&amp;state=XY1BToNAGIWvQv41SfdIOAmbFomodCCCC9M0ITVV0Wo1srBok4aIVmshNkZpoXIYZ4Zh1SuYinHh9n3ve68Fmt3UQQDRlArvFS8ucJKWwU0Z3DF3xoIJiz6LZYSTBbseMne2ynrkdkSn9ywOqw7OfBZMyPSSdA%2BLt1GRPlI3%2F3I6Ys2UZCSaEj25wukL6cc4DUvHZ%2Flx6bj07IkMxiTy8fK8EukwpN6c9H%2BvV1mPxh556LB8gJNn0TLrSCJHXRLN2ceYvZ%2BKtSr6kf%2F%2BgAfFskCAhrF5wLVkxHGKoRt7AtfQ99UNGbVlJKO1%2BQ%2FWld2KAg876wHgwdbUpgoC6Ntbmg3tbw%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><p>一些属性是不能继承的——举个例子如果你在一个元素上设置 <a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Properties/width" target="_blank" rel="noopener noreferrer"><code>width</code></a> 为 50% ，所有的后代不会是父元素的宽度的 50% 。如果这个也可以继承的话，CSS 就会很难使用了！</p><p>**备注：**在 MDN CSS 属性参考页面，你会发现一个名为“形式定义”的技术信息框，其中列举了属性的很多数据信息，包括能否被继承。以 <a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Properties/color#%E5%BD%A2%E5%BC%8F%E5%AE%9A%E4%B9%89" target="_blank" rel="noopener noreferrer">color 属性的形式定义部分</a>为例。</p><h2 id="理解这些概念是如何协同工作的" tabindex="-1"><a class="header-anchor" href="#理解这些概念是如何协同工作的"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E7%90%86%E8%A7%A3%E8%BF%99%E4%BA%9B%E6%A6%82%E5%BF%B5%E6%98%AF%E5%A6%82%E4%BD%95%E5%8D%8F%E5%90%8C%E5%B7%A5%E4%BD%9C%E7%9A%84" target="_blank" rel="noopener noreferrer">理解这些概念是如何协同工作的</a></span></a></h2><p>这三个概念一起来控制 CSS 规则应用于哪个元素；在下面的内容中，我们将看到它们是如何协同工作的。有时候会感觉有些复杂，但是当你对 CSS 有更多经验的时候，你就可以记住它们，即便忘记了细节，可以在网上查到，有经验的开发人员也不会记得所有细节。</p><p>以下视频展示了如何使用 Firefox 的开发者工具来检查网页的级联和优先级等：</p><h2 id="理解继承" tabindex="-1"><a class="header-anchor" href="#理解继承"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E7%90%86%E8%A7%A3%E7%BB%A7%E6%89%BF" target="_blank" rel="noopener noreferrer">理解继承</a></span></a></h2><p>我们从继承开始。下面的例子中我们有一个 <a href="https://developer.mozilla.org/zh-CN/docs/Web/HTML/Reference/Elements/ul" target="_blank" rel="noopener noreferrer"><code>&amp;lt;ul&amp;gt;</code></a> 元素，里面有两个无序列表。我们已经给 <code>&amp;lt;ul&amp;gt;</code> 设置了边框（border）、内边距（padding）和字体颜色。</p><p><code>color</code> 属性是一个继承属性。因此，<code>color</code> 属性应用在直接子元素和其后代——直接子元素 <code>&amp;lt;li&amp;gt;</code> 和第一个嵌套列表中的子项。然后添加了一个 <code>special</code> 类到第二个嵌套列表，其中使用了不同的颜色。然后通过它的子元素继承。</p><p>htmlCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=8fb6ae6a39ab2fa984dc3a047b10d53ea8fb0e4c&amp;state=fVBLTsMwEL3KaNiGVHF2rulJvHEc0xgmdhQnAqnqSVhxAfacCHEL5Mb5EAlW9ryf3swFm6El5ChGAk0qhAeJrbJO4kk6AEH29P3%2B%2BfX2AYU4kF3A%2BAIkik2TGCnhk4blq2fF2AYTh2T5O7tcspd%2BoTPaKkoV5%2BT5D1DmxTpsS83SMi921bYM2zFLyWnYLVT%2Bu1CaMUMdAnLM423hEhXak%2B859KYyWqtu7Dsyx0hUvq9Nz4F1rxA82RrutNY3qlN1bd2ZQ2Hao3RX6aTL0zl%2BpVak9PPN8ujdcP9i7LkZOFSe6smHGT7FQpjh0JjWIEeKGrz%2BAA%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;ul class=&quot;main&quot;&gt;</span>
<span class="line">  &lt;li&gt;项目 1&lt;/li&gt;</span>
<span class="line">  &lt;li&gt;</span>
<span class="line">    项目 2</span>
<span class="line">    &lt;ul&gt;</span>
<span class="line">      &lt;li&gt;2.1&lt;/li&gt;</span>
<span class="line">      &lt;li&gt;2.2&lt;/li&gt;</span>
<span class="line">    &lt;/ul&gt;</span>
<span class="line">  &lt;/li&gt;</span>
<span class="line">  &lt;li&gt;</span>
<span class="line">    项目 3</span>
<span class="line">    &lt;ul class=&quot;special&quot;&gt;</span>
<span class="line">      &lt;li&gt;</span>
<span class="line">        3.1</span>
<span class="line">        &lt;ul&gt;</span>
<span class="line">          &lt;li&gt;3.1.1&lt;/li&gt;</span>
<span class="line">          &lt;li&gt;3.1.2&lt;/li&gt;</span>
<span class="line">        &lt;/ul&gt;</span>
<span class="line">      &lt;/li&gt;</span>
<span class="line">      &lt;li&gt;3.2&lt;/li&gt;</span>
<span class="line">    &lt;/ul&gt;</span>
<span class="line">  &lt;/li&gt;</span>
<span class="line">&lt;/ul&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>cssCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=8fb6ae6a39ab2fa984dc3a047b10d53ea8fb0e4c&amp;state=fVBLTsMwEL3KaNiGVHF2rulJvHEc0xgmdhQnAqnqSVhxAfacCHEL5Mb5EAlW9ryf3swFm6El5ChGAk0qhAeJrbJO4kk6AEH29P3%2B%2BfX2AYU4kF3A%2BAIkik2TGCnhk4blq2fF2AYTh2T5O7tcspd%2BoTPaKkoV5%2BT5D1DmxTpsS83SMi921bYM2zFLyWnYLVT%2Bu1CaMUMdAnLM423hEhXak%2B859KYyWqtu7Dsyx0hUvq9Nz4F1rxA82RrutNY3qlN1bd2ZQ2Hao3RX6aTL0zl%2BpVak9PPN8ujdcP9i7LkZOFSe6smHGT7FQpjh0JjWIEeKGrz%2BAA%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">.main {</span>
<span class="line">  color: rebeccapurple;</span>
<span class="line">  border: 2px solid #ccc;</span>
<span class="line">  padding: 1em;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">.special {</span>
<span class="line">  color: black;</span>
<span class="line">  font-weight: bold;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://developer.mozilla.org/zh-CN/play?uuid=8fb6ae6a39ab2fa984dc3a047b10d53ea8fb0e4c&amp;state=fVBLTsMwEL3KaNiGVHF2rulJvHEc0xgmdhQnAqnqSVhxAfacCHEL5Mb5EAlW9ryf3swFm6El5ChGAk0qhAeJrbJO4kk6AEH29P3%2B%2BfX2AYU4kF3A%2BAIkik2TGCnhk4blq2fF2AYTh2T5O7tcspd%2BoTPaKkoV5%2BT5D1DmxTpsS83SMi921bYM2zFLyWnYLVT%2Bu1CaMUMdAnLM423hEhXak%2B859KYyWqtu7Dsyx0hUvq9Nz4F1rxA82RrutNY3qlN1bd2ZQ2Hao3RX6aTL0zl%2BpVak9PPN8ujdcP9i7LkZOFSe6smHGT7FQpjh0JjWIEeKGrz%2BAA%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><p>像 <code>width</code>（上面提到的）、<code>margin</code>、<code>padding</code> 和 <code>border</code> 不会被继承。如果 border 可以被继承，每个列表和列表项都会获得一个边框——可能就不是我们想要的结果！</p><p>尽管每个 CSS 属性页都列出了属性是否被继承，但我们通常可以通过常识来判断哪些属性属于默认继承。</p><h3 id="控制继承" tabindex="-1"><a class="header-anchor" href="#控制继承"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E6%8E%A7%E5%88%B6%E7%BB%A7%E6%89%BF" target="_blank" rel="noopener noreferrer">控制继承</a></span></a></h3><p>CSS 为控制继承提供了五个特殊的通用属性值。每个 CSS 属性都接收这些值：</p><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Values/inherit" target="_blank" rel="noopener noreferrer"><code>inherit</code></a> 设置该属性会使子元素属性和父元素相同。实际上，就是“开启继承”。</p><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Values/initial" target="_blank" rel="noopener noreferrer"><code>initial</code></a> 将应用于选定元素的属性值设置为该属性的<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Guides/Cascade/Property_value_processing#%E5%88%9D%E5%A7%8B%E5%80%BC" target="_blank" rel="noopener noreferrer">初始值</a>。</p><p><a href="https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Values/revert" target="_blank" rel="noopener noreferrer"><code>revert</code></a> 将应用于选定元素的属性值重置为浏览器的默认样式，而不是应用于该属性的默认值。在许多情况下，此值的作用类似于 <a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Values/unset" target="_blank" rel="noopener noreferrer"><code>unset</code></a>。</p><p><a href="https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Values/revert-layer" target="_blank" rel="noopener noreferrer"><code>revert-layer</code></a> 将应用于选定元素的属性值重置为在上一个<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/At-rules/@layer" target="_blank" rel="noopener noreferrer">层叠层</a>中建立的值。</p><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Values/unset" target="_blank" rel="noopener noreferrer"><code>unset</code></a> 将属性重置为自然值，也就是如果属性是自然继承那么就是 <code>inherit</code>，否则和 <code>initial</code> 一样</p><p>**备注：**见 <a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Guides/Cascade/Introduction#css_%E5%A3%B0%E6%98%8E%E7%9A%84%E6%BA%90" target="_blank" rel="noopener noreferrer">CSS 声明的源</a>有更多信息和具体是怎么工作的。</p><p>我们可以查看一个链接列表来探索这些值是如何运作的。在下面的实例中，你可以通过修改 CSS 来查看它们的功能，写代码是掌握 HTML 和 CSS 最好的办法。</p><p>示例：</p><ol><li>第二个列表项应用了类 <code>my-class-1</code>。它设置了内部元素来继承属性。如果你删除这个类，它会如何改变链接的颜色？</li><li>你知道为什么第三个和第四个链接会是这样的颜色？第三个链接设置了 <code>initial</code>，这意味着它使用了属性的初始值（在本例中为黑色），而不是链接的浏览器默认样式的蓝色。第四个设置了 <code>unset</code>，这意味着链接文本会使用其父元素的颜色——绿色。</li><li>如果你为 <code>&amp;lt;a&amp;gt;</code> 元素定义新的颜色（例如：<code>a { color: red; }</code>），哪些链接会改变颜色？</li><li>阅读下一节有关重置所有属性的内容后，回到这里，并将 <code>color</code> 属性改为 <code>all</code> 属性。注意第二个链接是怎么出现在新的一行中，还带有一个无序列表的符号的。你认为继承了哪些属性。</li></ol><p>htmlCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=bec363adf0d1b29332b174fb3723def388804001&amp;state=q1bKKMnNUbJSsinNsYvJU1Cwycm0e7l7xot1S2wSFTKKUtNsY5SUY5TsXk7e96xvqY1%2Bot3LRXNedG6y0c%2FJhGlQSM5JLC62jVHKrdQFM3UNY5Tsnu9e%2FqxzPyWmGIF0tPc%2B37uOElOMY5TsnvZPe7atA78pz2e1vFi3D2QZxDgbfXCQKOkoJRcXK1kpJeWnVCpUg6xJzs%2FJL7JSSC9KTc2zjsmrjcmLydND%2BF0hEUVZZl5GalFmCaZCIwyFmSWZiTmYCo3RFJbmFadCzVPSUcoCOU5JR6kkIzU3VclKKSczPaNEqRYA&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;ul&gt;</span>
<span class="line">  &lt;li&gt;默认&lt;a href=&quot;#&quot;&gt;链接&lt;/a&gt;颜色&lt;/li&gt;</span>
<span class="line">  &lt;li class=&quot;my-class-1&quot;&gt;继承&lt;a href=&quot;#&quot;&gt;链接&lt;/a&gt;颜色&lt;/li&gt;</span>
<span class="line">  &lt;li class=&quot;my-class-2&quot;&gt;重置&lt;a href=&quot;#&quot;&gt;链接&lt;/a&gt;颜色&lt;/li&gt;</span>
<span class="line">  &lt;li class=&quot;my-class-3&quot;&gt;取消&lt;a href=&quot;#&quot;&gt;链接&lt;/a&gt;颜色的设置&lt;/li&gt;</span>
<span class="line">&lt;/ul&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>cssCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=bec363adf0d1b29332b174fb3723def388804001&amp;state=q1bKKMnNUbJSsinNsYvJU1Cwycm0e7l7xot1S2wSFTKKUtNsY5SUY5TsXk7e96xvqY1%2Bot3LRXNedG6y0c%2FJhGlQSM5JLC62jVHKrdQFM3UNY5Tsnu9e%2FqxzPyWmGIF0tPc%2B37uOElOMY5TsnvZPe7atA78pz2e1vFi3D2QZxDgbfXCQKOkoJRcXK1kpJeWnVCpUg6xJzs%2FJL7JSSC9KTc2zjsmrjcmLydND%2BF0hEUVZZl5GalFmCaZCIwyFmSWZiTmYCo3RFJbmFadCzVPSUcoCOU5JR6kkIzU3VclKKSczPaNEqRYA&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">body {</span>
<span class="line">  color: green;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">.my-class-1 a {</span>
<span class="line">  color: inherit;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">.my-class-2 a {</span>
<span class="line">  color: initial;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">.my-class-3 a {</span>
<span class="line">  color: unset;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://developer.mozilla.org/zh-CN/play?uuid=bec363adf0d1b29332b174fb3723def388804001&amp;state=q1bKKMnNUbJSsinNsYvJU1Cwycm0e7l7xot1S2wSFTKKUtNsY5SUY5TsXk7e96xvqY1%2Bot3LRXNedG6y0c%2FJhGlQSM5JLC62jVHKrdQFM3UNY5Tsnu9e%2FqxzPyWmGIF0tPc%2B37uOElOMY5TsnvZPe7atA78pz2e1vFi3D2QZxDgbfXCQKOkoJRcXK1kpJeWnVCpUg6xJzs%2FJL7JSSC9KTc2zjsmrjcmLydND%2BF0hEUVZZl5GalFmCaZCIwyFmSWZiTmYCo3RFJbmFadCzVPSUcoCOU5JR6kkIzU3VclKKSczPaNEqRYA&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><h3 id="重设所有属性值" tabindex="-1"><a class="header-anchor" href="#重设所有属性值"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E9%87%8D%E8%AE%BE%E6%89%80%E6%9C%89%E5%B1%9E%E6%80%A7%E5%80%BC" target="_blank" rel="noopener noreferrer">重设所有属性值</a></span></a></h3><p>CSS 的简写属性 <a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Properties/all" target="_blank" rel="noopener noreferrer"><code>all</code></a> 可以用于同时将这些继承值中的一个应用于（几乎）所有属性。它的值可以是其中任意一个（<code>inherit</code>、<code>initial</code>、<code>unset</code> 或 <code>revert</code>）。这是一种撤销对样式所做更改的简便方法，以便回到之前已知的起点。</p><p>下面的示例中有两个块级引用元素。第一个用元素本身的样式，第二个设置 <code>all</code> 为 <code>unset</code></p><p>htmlCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=4b0f110b6d6c296c6e1130e481150bbfc53c8ba5&amp;state=fc6xqsIwFAbgVwlnrgp3jLVPkqVNY1s9JjVJQRBXwUEcVFwUHMXB9cJFfRqjPsalFkEHnf9zvv8fQmp7CBT8CBXv9gtlRcAkIX4euNPcTaZus3LH5W2xux%2FOt9Ph8je%2Bbn%2FdceY38oBJv%2FH2x%2BSLQziGxrQYtLNBzaaZYfCBvq73lf6FBg%2B4MUDhpWBYclHIu4lWhYxrXKHSlCgdykQ0H6HSsdCU%2FOQDYhRmMYmwKKNRObb%2BXFZJISIlhTTCVgfgQadsBA9sKnoCKGCWpBZG%2Fw%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;blockquote&gt;</span>
<span class="line">  &lt;p&gt;当前块引用设置了样式&lt;/p&gt;</span>
<span class="line">&lt;/blockquote&gt;</span>
<span class="line"></span>
<span class="line">&lt;blockquote class=&quot;fix-this&quot;&gt;</span>
<span class="line">  &lt;p&gt;当前块引用未设置样式&lt;/p&gt;</span>
<span class="line">&lt;/blockquote&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>cssCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=4b0f110b6d6c296c6e1130e481150bbfc53c8ba5&amp;state=fc6xqsIwFAbgVwlnrgp3jLVPkqVNY1s9JjVJQRBXwUEcVFwUHMXB9cJFfRqjPsalFkEHnf9zvv8fQmp7CBT8CBXv9gtlRcAkIX4euNPcTaZus3LH5W2xux%2FOt9Ph8je%2Bbn%2FdceY38oBJv%2FH2x%2BSLQziGxrQYtLNBzaaZYfCBvq73lf6FBg%2B4MUDhpWBYclHIu4lWhYxrXKHSlCgdykQ0H6HSsdCU%2FOQDYhRmMYmwKKNRObb%2BXFZJISIlhTTCVgfgQadsBA9sKnoCKGCWpBZG%2Fw%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">blockquote {</span>
<span class="line">  background-color: orange;</span>
<span class="line">  border: 2px solid blue;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">.fix-this {</span>
<span class="line">  all: unset;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://developer.mozilla.org/zh-CN/play?uuid=4b0f110b6d6c296c6e1130e481150bbfc53c8ba5&amp;state=fc6xqsIwFAbgVwlnrgp3jLVPkqVNY1s9JjVJQRBXwUEcVFwUHMXB9cJFfRqjPsalFkEHnf9zvv8fQmp7CBT8CBXv9gtlRcAkIX4euNPcTaZus3LH5W2xux%2FOt9Ph8je%2Bbn%2FdceY38oBJv%2FH2x%2BSLQziGxrQYtLNBzaaZYfCBvq73lf6FBg%2B4MUDhpWBYclHIu4lWhYxrXKHSlCgdykQ0H6HSsdCU%2FOQDYhRmMYmwKKNRObb%2BXFZJISIlhTTCVgfgQadsBA9sKnoCKGCWpBZG%2Fw%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><p>试着将 <code>all</code> 改成其他可用的值然后观察有什么不一样。</p><h2 id="理解层叠" tabindex="-1"><a class="header-anchor" href="#理解层叠"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E7%90%86%E8%A7%A3%E5%B1%82%E5%8F%A0" target="_blank" rel="noopener noreferrer">理解层叠</a></span></a></h2><p>我们现在明白了为什么嵌套在 HTML 结构中的段落和应用于正文中的 CSS 颜色相同，从入门课程中，我们了解了如何将文档中的任何修改应用于某个对象的 CSS，无论是把 CSS 指定某个元素还是创建一个类。现在，我们将要了解层叠如何定义在不止一个元素的时候怎么应用 CSS 规则。</p><p>有三个因素需要考虑，根据重要性排序如下，后面的更重要：</p><ol><li><strong>资源顺序</strong></li><li><strong>优先级</strong></li><li><strong>重要程度</strong></li></ol><p>我们从上往下看，看看浏览器是如何决定该应用哪个 CSS 规则的。</p><h3 id="资源顺序" tabindex="-1"><a class="header-anchor" href="#资源顺序"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E8%B5%84%E6%BA%90%E9%A1%BA%E5%BA%8F" target="_blank" rel="noopener noreferrer">资源顺序</a></span></a></h3><p>我们已经看到了顺序对于层叠的重要性。如果你有超过一条规则，而且都是相同的权重，那么最后面的规则会应用。可以理解为后面的规则覆盖前面的规则，直到最后一个开始设置样式。</p><p>资源顺序仅在规则的优先级相同时才体现出来，下面让我们看一下优先级：</p><h3 id="优先级-1" tabindex="-1"><a class="header-anchor" href="#优先级-1"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E4%BC%98%E5%85%88%E7%BA%A7_2" target="_blank" rel="noopener noreferrer">优先级</a></span></a></h3><p>你会发现在一些情况下，有些规则在最后出现，但是却应用了前面的具有冲突的规则。这是因为前面的有更高的<strong>优先级</strong>——它范围更小，因此浏览器就把它选择为元素的样式。</p><p>就像前面看到的，类选择器的权重大于元素选择器，因此类上定义的属性将覆盖应用于元素上的属性。</p><p>这里需要注意虽然我们考虑的是选择器，以及应用在选中对象上的规则，但不会覆盖所有规则，只覆盖相同的属性。</p><p>这样可以避免重复的 CSS。一种常见的做法是给基本元素定义通用样式，然后给不同的元素创建对应的类。举个例子，在下面的样式中我给 2 级标题定义了通用样式，然后创建了一些类只修改部分属性的值。最初定义的值应用于所有标题，然后更具体的值通过对应类来实现。</p><p>htmlCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=86f13250294d19adb454cb0a63a504c9a4473707&amp;state=hY%2BxSgQxEIZfZRjbqGvK7LqtnYVYpsmF2UskyR7JiuhynegriFiIpcWBraJPI7f6FrIbERXB9uP7%2BGd6NJ13KLAyvF7f3L%2BtXobn1fDwNFyfr28v3%2B%2Buqm3Daxkqw0E7ldKuxOSVcxLrLL8%2BXsBE4J9sFu3cdD%2B6jP4KkaFOCQUaDr0MAE0bus1kz0gAJ1%2BOSLeujQI2iqIov5RGeetOBexRG%2BdWMZB4aD0l2KcTOGi9ChIZTIhBomibUoalDDJs5S9%2Br%2B1Ma9n4vLf%2Fth5pRlqrxXFcOMoiMjwaT0eGnSFPKNCNHS4%2FAA%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;h2&gt;未设置类的标题&lt;/h2&gt;</span>
<span class="line">&lt;h2 class=&quot;small&quot;&gt;设置了 small 类的标题&lt;/h2&gt;</span>
<span class="line">&lt;h2 class=&quot;bright&quot;&gt;设置了 bright 类的标题&lt;/h2&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>cssCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=86f13250294d19adb454cb0a63a504c9a4473707&amp;state=hY%2BxSgQxEIZfZRjbqGvK7LqtnYVYpsmF2UskyR7JiuhynegriFiIpcWBraJPI7f6FrIbERXB9uP7%2BGd6NJ13KLAyvF7f3L%2BtXobn1fDwNFyfr28v3%2B%2Buqm3Daxkqw0E7ldKuxOSVcxLrLL8%2BXsBE4J9sFu3cdD%2B6jP4KkaFOCQUaDr0MAE0bus1kz0gAJ1%2BOSLeujQI2iqIov5RGeetOBexRG%2BdWMZB4aD0l2KcTOGi9ChIZTIhBomibUoalDDJs5S9%2Br%2B1Ma9n4vLf%2Fth5pRlqrxXFcOMoiMjwaT0eGnSFPKNCNHS4%2FAA%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">h2 {</span>
<span class="line">  font-size: 2em;</span>
<span class="line">  color: #000;</span>
<span class="line">  font-family: Georgia, &quot;Times New Roman&quot;, Times, serif;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">.small {</span>
<span class="line">  font-size: 1em;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">.bright {</span>
<span class="line">  color: rebeccapurple;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://developer.mozilla.org/zh-CN/play?uuid=86f13250294d19adb454cb0a63a504c9a4473707&amp;state=hY%2BxSgQxEIZfZRjbqGvK7LqtnYVYpsmF2UskyR7JiuhynegriFiIpcWBraJPI7f6FrIbERXB9uP7%2BGd6NJ13KLAyvF7f3L%2BtXobn1fDwNFyfr28v3%2B%2Buqm3Daxkqw0E7ldKuxOSVcxLrLL8%2BXsBE4J9sFu3cdD%2B6jP4KkaFOCQUaDr0MAE0bus1kz0gAJ1%2BOSLeujQI2iqIov5RGeetOBexRG%2BdWMZB4aD0l2KcTOGi9ChIZTIhBomibUoalDDJs5S9%2Br%2B1Ma9n4vLf%2Fth5pRlqrxXFcOMoiMjwaT0eGnSFPKNCNHS4%2FAA%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><p>现在让我们来看看浏览器如何计算优先级。我们已经知道一个元素选择器比类选择器的优先级更低，会被其覆盖。本质上，不同类型的选择器有不同的分数值，把这些分数相加就得到特定选择器的权重，然后就可以进行匹配。</p><p>一个选择器的优先级可以说是由三个不同的值（或分量）相加，可以认为是百（ID）十（类）个（元素）——三位数的三个位数：</p><ul><li><strong>ID</strong>：选择器中包含 ID 选择器则百位得一分。</li><li><strong>类</strong>：选择器中包含类选择器、属性选择器或者伪类则十位得一分。</li><li><strong>元素</strong>：选择器中包含元素、伪元素选择器则个位得一分。</li></ul><p>**备注：**通用选择器（<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Selectors/Universal_selectors" target="_blank" rel="noopener noreferrer"><code>*</code></a>）、组合符（<code>+</code>、<code>&amp;gt;</code>、<code>~</code>、&#39; &#39;）和调整优先级的选择器（<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Selectors/:where" target="_blank" rel="noopener noreferrer"><code>:where()</code></a>）不会影响优先级。</p><p>否定（<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Selectors/:not" target="_blank" rel="noopener noreferrer"><code>:not()</code></a>）和任意匹配（<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Selectors/:is" target="_blank" rel="noopener noreferrer"><code>:is()</code></a>）伪类本身对优先级没有影响，但它们的参数则会带来影响。参数中，对优先级算法有贡献的参数的优先级的最大值将作为该伪类选择器的优先级。</p><p>下面有几个单独的例子，有空可以看看。试着思考下，理解为什么优先级是这样定的。我们还没有深入介绍选择器，不过你可以在 MDN 的<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Guides/Selectors" target="_blank" rel="noopener noreferrer">选择器参考页面</a>找到每个选择器的详细信息。</p><table><thead><tr><th>选择器</th><th>ID</th><th>类</th><th>元素</th><th>优先级</th></tr></thead><tbody><tr><td><code>h1</code></td><td>0</td><td>0</td><td>1</td><td>0-0-1</td></tr><tr><td><code>h1 + p::first-letter</code></td><td>0</td><td>0</td><td>3</td><td>0-0-3</td></tr><tr><td><code>li &amp;gt; a[href*=&quot;en-US&quot;] &amp;gt; .inline-warning</code></td><td>0</td><td>2</td><td>2</td><td>0-2-2</td></tr><tr><td><code>#identifier</code></td><td>1</td><td>0</td><td>0</td><td>1-0-0</td></tr><tr><td><code>button:not(#mainBtn, .cta)</code></td><td>1</td><td>0</td><td>1</td><td>1-0-1</td></tr></tbody></table><p>在我们继续之前，先看看这个示例。</p><p>htmlCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=d7048d6aacda1b281b507c97af4468f4b6a29822&amp;state=jZNLjtNAEIavUupsIJoe5wVIjZOT9Kbt7omLqVRbdjsPRpHYILHgAIgLcAU0muMMYskVkB07OAmgLFp21%2BP7%2FyqpH0QWViSUiC2uISVTlnMtUs%2FBILtCC0A718JXob4sNAP8vxKZj5UAcUXtH0BMeGxjs9ZiERvICnc312KgxeL5%2B4c4Mos4Iry%2B5%2FHzWU8ctZJxZHG90Nx9xY1Iy1IoEQ1hfAvPT19%2BfPz08%2FHbr6evYzmSYxhGmgfNoGDgoUYkJr1fFr5iK1NPvlBQOPtW816z5mgIk1PM5BwzaJbxb1pClevhppeuZn1cvfeKgLAjtpidI%2FKbHmh2DhrL6V9At2zWZ6hNhqFv6dUpaSQnraUaUR9CxSGTaYZkX0xeglGZX7uindgX1hUKxqN8C6UntJCQSe97Aq8vBaZHgevh1pSZu6S%2FOadPe%2FT61Cu4WsNXCblTjXZ7FsuczE4BMiE7mZBvagCaa%2BZwmQUFs1G%2BbaJ3noMs8b1TMOliwW2DtC71hQnoWQF7dn8yhnDJClLHwRVNeIM2ZDWgI6xMsUSWiQ%2FBrw6mO58VHYzmxlrkpYJRlyE8ZAjLIMuwIyfDLndH%2BX3zct7VD0fciJC5lRNKUD2Q2P8G&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;div class=&quot;container&quot; id=&quot;outer&quot;&gt;</span>
<span class="line">  &lt;div class=&quot;container&quot; id=&quot;inner&quot;&gt;</span>
<span class="line">    &lt;ul&gt;</span>
<span class="line">      &lt;li class=&quot;nav&quot;&gt;&lt;a href=&quot;#&quot;&gt;一&lt;/a&gt;&lt;/li&gt;</span>
<span class="line">      &lt;li class=&quot;nav&quot;&gt;&lt;a href=&quot;#&quot;&gt;二&lt;/a&gt;&lt;/li&gt;</span>
<span class="line">    &lt;/ul&gt;</span>
<span class="line">  &lt;/div&gt;</span>
<span class="line">&lt;/div&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>cssCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=d7048d6aacda1b281b507c97af4468f4b6a29822&amp;state=jZNLjtNAEIavUupsIJoe5wVIjZOT9Kbt7omLqVRbdjsPRpHYILHgAIgLcAU0muMMYskVkB07OAmgLFp21%2BP7%2FyqpH0QWViSUiC2uISVTlnMtUs%2FBILtCC0A718JXob4sNAP8vxKZj5UAcUXtH0BMeGxjs9ZiERvICnc312KgxeL5%2B4c4Mos4Iry%2B5%2FHzWU8ctZJxZHG90Nx9xY1Iy1IoEQ1hfAvPT19%2BfPz08%2FHbr6evYzmSYxhGmgfNoGDgoUYkJr1fFr5iK1NPvlBQOPtW816z5mgIk1PM5BwzaJbxb1pClevhppeuZn1cvfeKgLAjtpidI%2FKbHmh2DhrL6V9At2zWZ6hNhqFv6dUpaSQnraUaUR9CxSGTaYZkX0xeglGZX7uindgX1hUKxqN8C6UntJCQSe97Aq8vBaZHgevh1pSZu6S%2FOadPe%2FT61Cu4WsNXCblTjXZ7FsuczE4BMiE7mZBvagCaa%2BZwmQUFs1G%2BbaJ3noMs8b1TMOliwW2DtC71hQnoWQF7dn8yhnDJClLHwRVNeIM2ZDWgI6xMsUSWiQ%2FBrw6mO58VHYzmxlrkpYJRlyE8ZAjLIMuwIyfDLndH%2BX3zct7VD0fciJC5lRNKUD2Q2P8G&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">/* 1. 优先级：1-0-1 */</span>
<span class="line">#outer a {</span>
<span class="line">  background-color: red;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">/* 2. 优先级：2-0-1 */</span>
<span class="line">#outer #inner a {</span>
<span class="line">  background-color: blue;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">/* 3. 优先级：1-0-4 */</span>
<span class="line">#outer div ul li a {</span>
<span class="line">  color: yellow;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">/* 4. 优先级：1-1-3 */</span>
<span class="line">#outer div ul .nav a {</span>
<span class="line">  color: white;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">/* 5. 优先级：0-2-4 */</span>
<span class="line">div div li:nth-child(2) a:hover {</span>
<span class="line">  border: 10px solid black;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">/* 6. 优先级：0-2-3 */</span>
<span class="line">div li:nth-child(2) a:hover {</span>
<span class="line">  border: 10px dashed black;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">/* 7. 优先级：0-3-3 */</span>
<span class="line">div div .nav:nth-child(2) a:hover {</span>
<span class="line">  border: 10px double black;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">a {</span>
<span class="line">  display: inline-block;</span>
<span class="line">  line-height: 40px;</span>
<span class="line">  font-size: 20px;</span>
<span class="line">  text-decoration: none;</span>
<span class="line">  text-align: center;</span>
<span class="line">  width: 200px;</span>
<span class="line">  margin-bottom: 10px;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">ul {</span>
<span class="line">  padding: 0;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">li {</span>
<span class="line">  list-style-type: none;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://developer.mozilla.org/zh-CN/play?uuid=d7048d6aacda1b281b507c97af4468f4b6a29822&amp;state=jZNLjtNAEIavUupsIJoe5wVIjZOT9Kbt7omLqVRbdjsPRpHYILHgAIgLcAU0muMMYskVkB07OAmgLFp21%2BP7%2FyqpH0QWViSUiC2uISVTlnMtUs%2FBILtCC0A718JXob4sNAP8vxKZj5UAcUXtH0BMeGxjs9ZiERvICnc312KgxeL5%2B4c4Mos4Iry%2B5%2FHzWU8ctZJxZHG90Nx9xY1Iy1IoEQ1hfAvPT19%2BfPz08%2FHbr6evYzmSYxhGmgfNoGDgoUYkJr1fFr5iK1NPvlBQOPtW816z5mgIk1PM5BwzaJbxb1pClevhppeuZn1cvfeKgLAjtpidI%2FKbHmh2DhrL6V9At2zWZ6hNhqFv6dUpaSQnraUaUR9CxSGTaYZkX0xeglGZX7uindgX1hUKxqN8C6UntJCQSe97Aq8vBaZHgevh1pSZu6S%2FOadPe%2FT61Cu4WsNXCblTjXZ7FsuczE4BMiE7mZBvagCaa%2BZwmQUFs1G%2BbaJ3noMs8b1TMOliwW2DtC71hQnoWQF7dn8yhnDJClLHwRVNeIM2ZDWgI6xMsUSWiQ%2FBrw6mO58VHYzmxlrkpYJRlyE8ZAjLIMuwIyfDLndH%2BX3zct7VD0fciJC5lRNKUD2Q2P8G&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><p>这里发生了什么？首先，我们先看看最上面的选择器规则，你会发现，我们已经把优先级计算出来放在最前面的注释里。</p><ul><li>前面两个选择器都是链接背景颜色的样式——第二个赢了使得背景变成蓝色，因为它多了一个 ID 选择器：优先级 2-0-1 vs. 1-0-1。</li><li>第三四个选择器都是链接文本颜色样式——后者赢了使得文本变成白色，因为它虽然少一个元素选择器，但是多了一个类选择器。所以优先级是 1-1-3 vs. 1-0-4。</li><li>第 5 到 7 个选择器都是鼠标悬停时链接边框样式。第六个显然输给了第五个，优先级是 0-2-3 vs. 0-2-4——少了个元素选择器。第七个，比第五第六都高——子选择器数量相同，但是有一个元素选择器变成类选择器。所以最后优先级是 0-3-3 vs. 0-2-3 和 0-2-4。</li></ul><p><strong>备注：<strong>每一个选择器类编都有它自己的优先级等级，它们不会被具有较低优先级的选择器覆盖。例如，权重为_一百万_的</strong>类</strong>选择器不会覆盖权重为_一_的 <strong>ID</strong> 选择器。</p><p>评估优先级的最佳方法是对不同的优先级等级单独进行评分，并从最高的等级开始，必要时再计算低优先级等级的权重。即，仅当某一列的优先级权重相同时，你才需要评估下一列；否则，你可以直接忽略低等级的选择器，因为它们无法覆盖高优先级等级的选择器。</p><h3 id="内联样式" tabindex="-1"><a class="header-anchor" href="#内联样式"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E5%86%85%E8%81%94%E6%A0%B7%E5%BC%8F" target="_blank" rel="noopener noreferrer">内联样式</a></span></a></h3><p>内联样式，即 <a href="https://developer.mozilla.org/zh-CN/docs/Web/HTML/Reference/Global_attributes#style" target="_blank" rel="noopener noreferrer"><code>style</code></a> 属性内的样式声明，优先于所有普通的样式，无论其优先级如何。这样的声明没有选择器，但它们的优先级可以理解为 1-0-0-0；即无论选择器中有多少个 ID，它总是比其他任何优先级的权重都要高。</p><h3 id="important" tabindex="-1"><a class="header-anchor" href="#important"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#!important" target="_blank" rel="noopener noreferrer">!important</a></span></a></h3><p>有一个特殊的 CSS 可以用来覆盖所有上面所有优先级计算，不过需要很小心的使用——<code>!important</code>。用于修改特定属性的值，能够覆盖普通规则的层叠。</p><p>**备注：**了解 <code>!important</code> 是为了在阅读别人代码的时候知道有什么作用。<strong>但是，强烈建议除了非常情况不要使用它。</strong><code>!important</code> 改变了层叠的常规工作方式，它会使调试 CSS 问题非常困难，特别是在大型样式表中。</p><p>看看这个示例，有两个段落，其中一个有 ID。</p><p>htmlCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=1d080d309b159905576b08f59fc77ef030f72f70&amp;state=dc%2B9TsMwEAfwVzmONYAYWNyPJ%2FHixFZi6pwtx1WLqkqBBRAIMdKRDTqUCSkDiIchDWXiFRBNGZDoeHf%2F%2B%2BluglnIDTLsOkiMKIoex1iFoDzH%2Fupt1tw91dW8WTyvbl%2Ffy7Pugetz%2BicLWvY4jjSRppRjv67Kupp%2FlpfN1eNy9tDcXH8s7uuqXF6cf72ctgxGmBQFMtzd7MGEE0AskkHq7ZDkXmKN9Qy8kp31xHqpPINDN4bCGi0hNiIZdDhNOXHab4%2FZpqRenPxhyJKCHZ0764Og8Mu4bUBshmoNbOpRpkPbcEJKTSmDIzduGYzw%2BOc1jDBkKlfI0Og0Czj9Bg%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;p class=&quot;better&quot;&gt;这是个段落。&lt;/p&gt;</span>
<span class="line">&lt;p class=&quot;better&quot; id=&quot;winning&quot;&gt;一个选择器掌管一切！&lt;/p&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>cssCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=1d080d309b159905576b08f59fc77ef030f72f70&amp;state=dc%2B9TsMwEAfwVzmONYAYWNyPJ%2FHixFZi6pwtx1WLqkqBBRAIMdKRDTqUCSkDiIchDWXiFRBNGZDoeHf%2F%2B%2BluglnIDTLsOkiMKIoex1iFoDzH%2Fupt1tw91dW8WTyvbl%2Ffy7Pugetz%2BicLWvY4jjSRppRjv67Kupp%2FlpfN1eNy9tDcXH8s7uuqXF6cf72ctgxGmBQFMtzd7MGEE0AskkHq7ZDkXmKN9Qy8kp31xHqpPINDN4bCGi0hNiIZdDhNOXHab4%2FZpqRenPxhyJKCHZ0764Og8Mu4bUBshmoNbOpRpkPbcEJKTSmDIzduGYzw%2BOc1jDBkKlfI0Og0Czj9Bg%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">#winning {</span>
<span class="line">  background-color: red;</span>
<span class="line">  border: 1px solid black;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">.better {</span>
<span class="line">  background-color: gray;</span>
<span class="line">  border: none !important;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">p {</span>
<span class="line">  background-color: blue;</span>
<span class="line">  color: white;</span>
<span class="line">  padding: 5px;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://developer.mozilla.org/zh-CN/play?uuid=1d080d309b159905576b08f59fc77ef030f72f70&amp;state=dc%2B9TsMwEAfwVzmONYAYWNyPJ%2FHixFZi6pwtx1WLqkqBBRAIMdKRDTqUCSkDiIchDWXiFRBNGZDoeHf%2F%2B%2BluglnIDTLsOkiMKIoex1iFoDzH%2Fupt1tw91dW8WTyvbl%2Ffy7Pugetz%2BicLWvY4jjSRppRjv67Kupp%2FlpfN1eNy9tDcXH8s7uuqXF6cf72ctgxGmBQFMtzd7MGEE0AskkHq7ZDkXmKN9Qy8kp31xHqpPINDN4bCGi0hNiIZdDhNOXHab4%2FZpqRenPxhyJKCHZ0764Og8Mu4bUBshmoNbOpRpkPbcEJKTSmDIzduGYzw%2BOc1jDBkKlfI0Og0Czj9Bg%3D%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><p>让我们看看会发生什么——如果有什么疑问，试着删除一些属性：</p><ol><li>你会发现第三个规则 <a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Properties/color" target="_blank" rel="noopener noreferrer"><code>color</code></a> 和 <a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Properties/padding" target="_blank" rel="noopener noreferrer"><code>padding</code></a> 的值被应用了，但是 <a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/Properties/background-color" target="_blank" rel="noopener noreferrer"><code>background-color</code></a> 没有。为什么？应该三个都应用，因为顺序规则是后面覆盖前面。</li><li>无论如何，上面的规则赢了，因为类选择器比元素选择器有更高的优先级。</li><li>两个元素都有 <code>better</code> <a href="https://developer.mozilla.org/zh-CN/docs/Web/HTML/Reference/Global_attributes#class" target="_blank" rel="noopener noreferrer"><code>class</code></a>，但是第二个有 <a href="https://developer.mozilla.org/zh-CN/docs/Web/HTML/Reference/Global_attributes#id" target="_blank" rel="noopener noreferrer"><code>id</code></a> 。因为 ID 选择器比类选择器优先级更高（一个页面只能有一个独特的 ID，但是很多元素都有相同的类——ID 对于目标非常独特），红色背景和 1px 黑色边框应该都被应用到第二个元素，第一个元素应该是灰色背景和 no border，根据类选择器。</li><li>第二个元素有红色背景但是没有边框。为什么？因为 <code>!important</code> 声明在第二条规则里——在 <code>border: none</code> 后面，说明即使计算优先级低，这个属性也使用这个值。</li></ol><p>**备注：**覆盖 <code>!important</code> 唯一的办法就是另一个 <code>!important</code> 具有相同_优先级_而且顺序靠后，或者更高优先级。</p><p>在一种情况下，你可能不得不使用它：当你不能编辑核心的 CSS 模块，不能用任何其他方式覆盖，而你又真的想要覆盖一个样式时。但说真的，如果可以避免的话就不要用它。</p><h2 id="css-位置的影响" tabindex="-1"><a class="header-anchor" href="#css-位置的影响"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#css_%E4%BD%8D%E7%BD%AE%E7%9A%84%E5%BD%B1%E5%93%8D" target="_blank" rel="noopener noreferrer">CSS 位置的影响</a></span></a></h2><p>最后，也很有用，CSS 声明的优先级取决于定义它的样式表和级联层。</p><p>它让用户可以设置自定义样式表来覆盖开发人员定义的样式。例如用户可能视力受损，并想在所有网页上设置两倍的正常字体大小，以便更容易进行阅读。</p><p>也可以在级联层中声明开发人员定义的样式：你可以让非分层样式覆盖分层样式，或者你可以让后面的层中声明的样式覆盖先前的层中声明的样式。例如，作为开发人员，你可能无法编辑第三方的样式表，但你可以将外部的样式表导入级联层中，以便你自己的样式可以轻松地覆盖导入的样式，无需担心第三方选择器的优先级。</p><h3 id="覆盖声明的顺序" tabindex="-1"><a class="header-anchor" href="#覆盖声明的顺序"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E8%A6%86%E7%9B%96%E5%A3%B0%E6%98%8E%E7%9A%84%E9%A1%BA%E5%BA%8F" target="_blank" rel="noopener noreferrer">覆盖声明的顺序</a></span></a></h3><p>相互冲突的声明将按以下顺序应用，后一种声明将覆盖前一种声明：</p><ol><li><p>用户代理样式表中的声明（例如，浏览器的默认样式，在没有设置其他样式时使用）。</p></li><li><p>用户样式表中的常规声明（由用户设置的自定义样式）。</p></li><li><p>作者样式表中的常规声明（这些是我们 web 开发人员设置的样式）。</p></li><li><p>作者样式表中的 <code>!important</code> 声明</p></li><li><p>用户样式表中的 <code>!important</code> 声明</p></li><li><p>用户代理样式表中的 <code>!important</code> 声明</p></li></ol><p>**备注：**标记为 <code>!important</code> 的样式的优先级顺序是颠倒的。web 开发人员的样式表覆盖用户的样式表是有意义的，因此设计可以按预期进行，但是有时用户有充足的理由覆盖 web 开发人员的样式，正如上面提到的——这可以通过在他们的规则中使用 <code>!important</code> 来实现。</p><h2 id="级联层的顺序" tabindex="-1"><a class="header-anchor" href="#级联层的顺序"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E7%BA%A7%E8%81%94%E5%B1%82%E7%9A%84%E9%A1%BA%E5%BA%8F" target="_blank" rel="noopener noreferrer">级联层的顺序</a></span></a></h2><p>尽管<a href="https://developer.mozilla.org/zh-CN/docs/Web/CSS/Reference/At-rules/@layer" target="_blank" rel="noopener noreferrer">级联层</a>属于高级的主题，你可能不会立刻使用此特性，但了解层是如何级联的非常重要。</p><p>在级联层中声明 CSS 时，优先级的顺序由声明层的顺序来决定。在任何层之外声明的 CSS 样式会被按声明的顺序组合在一起，形成一个未命名的层，它会被当作最后声明的层。对于存在冲突的常规（没有 <code>!important</code> 声明）样式，后面的层比先前定义的层的优先级高。但对于带有 <code>!important</code> 标记的样式，其顺序相反——先前的层中的 important 样式比后面的层以及为在层中声明的 important 样式优先级要高。但内联样式比所有作者定义的样式的优先级都要高，不受级联层规则的影响。</p><p>当你在不同的层中有多个样式块，且其中提供了对于某一元素的单一属性的相互冲突的值时，声明该冲突样式的层的顺序将决定其优先级。而不是高优先级的层直接覆盖低优先级的层中的所有样式。需要注意的是单独的一个层中的样式的优先级仍旧会起作用。</p><p>htmlCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=b9d718997f73fcc9056d1223e9862c2d800730de&amp;state=hZK%2FTsMwEMZfxRxblarpwJJAxQOwsXpJ42ticG3LdlWiKhN%2FJKQOiA3EwgvAhBADvE1DHwMljaqmTcXmu0%2B%2B7%2FudPYPUjQUEcKwJZycUIsbONcZ8xGPuMgqDxe1n8XK%2F%2FPkqXu8Wj%2FPl9bx4ev99vinePpYP38c9PaASPIithQBORZShISNurDsrjx6xGCvJqiKkkkpNZlQS0usQv%2Bt3%2B6TTK8thFF8mRk0k68ZKKBMQgywslbpMDGbkgI%2B1Mi6SrpKGyjA0ATnSV4RLi47oidECQypzKvVhk2Xt29%2F0rUZ0rcsEBsQqwVnTJS8z72CtZrUarC382qINbigmGK7EujNNucNtwHW%2BKWcurUCb%2FTo3i2yKbPt23ky%2F8RCrpO0L2llRW%2F7EIMomgDKRTP4l6Pv7EJRz%2BxDAg4vyd4EHLsUxQgCCJ6mD%2FA8%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;p id=&quot;addSpecificity&quot;&gt;具有边框和背景的段落&lt;/p&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>cssCopy<a href="https://developer.mozilla.org/zh-CN/play?uuid=b9d718997f73fcc9056d1223e9862c2d800730de&amp;state=hZK%2FTsMwEMZfxRxblarpwJJAxQOwsXpJ42ticG3LdlWiKhN%2FJKQOiA3EwgvAhBADvE1DHwMljaqmTcXmu0%2B%2B7%2FudPYPUjQUEcKwJZycUIsbONcZ8xGPuMgqDxe1n8XK%2F%2FPkqXu8Wj%2FPl9bx4ev99vinePpYP38c9PaASPIithQBORZShISNurDsrjx6xGCvJqiKkkkpNZlQS0usQv%2Bt3%2B6TTK8thFF8mRk0k68ZKKBMQgywslbpMDGbkgI%2B1Mi6SrpKGyjA0ATnSV4RLi47oidECQypzKvVhk2Xt29%2F0rUZ0rcsEBsQqwVnTJS8z72CtZrUarC382qINbigmGK7EujNNucNtwHW%2BKWcurUCb%2FTo3i2yKbPt23ky%2F8RCrpO0L2llRW%2F7EIMomgDKRTP4l6Pv7EJRz%2BxDAg4vyd4EHLsUxQgCCJ6mD%2FA8%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">@layer firstLayer, secondLayer;</span>
<span class="line"></span>
<span class="line">p {</span>
<span class="line">  /* 0-0-1 */</span>
<span class="line">  background-color: red;</span>
<span class="line">  color: grey !important;</span>
<span class="line">  border: 5px inset purple;</span>
<span class="line">}</span>
<span class="line">p#addSpecificity {</span>
<span class="line">  /* 1-0-1 */</span>
<span class="line">  border-style: solid !important;</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">@layer firstLayer {</span>
<span class="line">  #addSpecificity {</span>
<span class="line">    /* 1-0-0 */</span>
<span class="line">    background-color: blue;</span>
<span class="line">    color: white !important;</span>
<span class="line">    border-width: 5px;</span>
<span class="line">    border-style: dashed !important;</span>
<span class="line">  }</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">@layer secondLayer {</span>
<span class="line">  p#addSpecificity {</span>
<span class="line">    /* 1-0-1 */</span>
<span class="line">    background-color: green;</span>
<span class="line">    color: orange !important;</span>
<span class="line">    border-width: 10px;</span>
<span class="line">    border-style: dotted !important;</span>
<span class="line">  }</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><a href="https://developer.mozilla.org/zh-CN/play?uuid=b9d718997f73fcc9056d1223e9862c2d800730de&amp;state=hZK%2FTsMwEMZfxRxblarpwJJAxQOwsXpJ42ticG3LdlWiKhN%2FJKQOiA3EwgvAhBADvE1DHwMljaqmTcXmu0%2B%2B7%2FudPYPUjQUEcKwJZycUIsbONcZ8xGPuMgqDxe1n8XK%2F%2FPkqXu8Wj%2FPl9bx4ev99vinePpYP38c9PaASPIithQBORZShISNurDsrjx6xGCvJqiKkkkpNZlQS0usQv%2Bt3%2B6TTK8thFF8mRk0k68ZKKBMQgywslbpMDGbkgI%2B1Mi6SrpKGyjA0ATnSV4RLi47oidECQypzKvVhk2Xt29%2F0rUZ0rcsEBsQqwVnTJS8z72CtZrUarC382qINbigmGK7EujNNucNtwHW%2BKWcurUCb%2FTo3i2yKbPt23ky%2F8RCrpO0L2llRW%2F7EIMomgDKRTP4l6Pv7EJRz%2BxDAg4vyd4EHLsUxQgCCJ6mD%2FA8%3D&amp;srcPrefix=%2Fzh-CN%2Fdocs%2FLearn_web_development%2FCore%2FStyling_basics%2FHandling_conflicts%2F" target="_blank" rel="noopener noreferrer">Play</a></p><p>让我们讨论一下上例以了解发生了什么。示例中，声明了两个级联层，按 <code>firstLayer</code> 和 <code>secondLayer</code> 的顺序声明。即使 <code>secondLayer</code> 的优先级更高，但其中声明的样式没有被使用。为什么？因为不分层的常规样式具有更高的优先级，覆盖了层中的常规样式，不论层的优先级如何，而具有 important 的样式，则是先前声明的层会覆盖后声明的层，而不是层的优先级。</p><p>如果你修改示例中 CSS 的第一行为 <code>@layer secondLayer, firstLayer;</code>，就会修改层声明的顺序，所有 <code>firstLayer</code> 中的 important 样式会被 <code>secondLayer</code> 中的冲突值覆盖。</p><h2 id="技能测试" tabindex="-1"><a class="header-anchor" href="#技能测试"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E6%8A%80%E8%83%BD%E6%B5%8B%E8%AF%95%EF%BC%81" target="_blank" rel="noopener noreferrer">技能测试！</a></span></a></h2><p>你已经阅读到了本文的末尾，但你记住最重要的内容了吗？在进一步学习之前，你可以寻找一些深入的测验来验证你是否掌握了这些信息，参见<a href="https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Styling_basics/Test_your_skills/Cascade" target="_blank" rel="noopener noreferrer">技能测试：层叠</a>。</p><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span><a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Handling_conflicts#%E6%80%BB%E7%BB%93" target="_blank" rel="noopener noreferrer">总结</a></span></a></h2><p>如果你理解了本文的大部分内容，那么就做得很好了——你已经开始熟悉 CSS 的基本机制。接下来，我们将详细讨论<a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Core/Styling_basics/Cascade_layers" target="_blank" rel="noopener noreferrer">层叠层</a>。</p><p>如果你没有完全理解层叠、优先级和继承，也请不要担心！这绝对是我们到目前为止在课程中所涉及到的最复杂的事情，即使是专业的 web 开发人员有时也会觉得棘手。我们建议你在继续学习这门课程的过程中，反复阅读这篇文章几次，并继续思考它。</p><p>如果你开始遇到样式没有按照预期应用的奇怪问题，请回到这里。这可能是一个特殊的问题。</p>`,151)])])}const o=n(i,[["render",r]]),p=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E4%B8%89%E4%BB%B6%E5%A5%97/%E6%A0%B7%E5%BC%8F/CSS/MDN%E6%96%87%E6%A1%A3/1%20%E5%9F%BA%E7%A1%80%E6%A0%B7%E5%BC%8F/4%20%E5%B1%82%E5%8F%A0%E3%80%81%E4%BC%98%E5%85%88%E7%BA%A7%E4%B8%8E%E7%BB%A7%E6%89%BF/1%20%E5%B1%82%E5%8F%A0%E3%80%81%E4%BC%98%E5%85%88%E7%BA%A7%E4%B8%8E%E7%BB%A7%E6%89%BF.html","title":"层叠、优先级与继承","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/三件套/样式/CSS/MDN文档/1 基础样式/4 层叠、优先级与继承/1 层叠、优先级与继承.md"}');exp